import * as React from "react"
import { Link, graphql, type PageProps } from "gatsby"

import { Layout } from "../components/layout"
import { Seo } from "../components/seo"
import { Article } from "../components/article"
import { useTranslation } from '../utils/i18n'
import { Post } from "../types"

function IndexRoute({ data, }: PageProps<DataProps>) {
  const { t } = useTranslation()
  const posts = data.allMarkdownRemark.nodes.filter(node =>
    node.fields.slug.startsWith("/blog/")
  )

  return (
    <Layout>
      <h2>{t('projects')}</h2>
      <ul>
        <li>
          <Link to="/projects/electronics-study/">{t('projects/electronics-study-list')}</Link>
        </li>
      </ul>
      <h2>{t('blog-latest')}</h2>
      <Article post={posts[0]} />
      <p>
        <Link to="/blog/">{t('blog-list')}</Link>
      </p>
    </Layout>
  )
}

export default IndexRoute

export function Head() {
  return <Seo title="Home" />
}

type DataProps = {
  allMarkdownRemark: {
    nodes: Post[]
  }
}

export const pageQuery = graphql`
  {
    allMarkdownRemark(limit: 2, sort: { frontmatter: { date: DESC } }) {
      nodes {
        excerpt
        html
        fields {
          slug
        }
        frontmatter {
          date(formatString: "MMMM DD, YYYY")
          title
          description
        }
      }
    }
  }
`
